extends Node

signal coin_changed(new_count: int)

var _count: int = 0
const SAVE_PATH := "user://save.json"

func _ready() -> void:
    load_save()


func add_coin() -> void:
    _count += 1
    save()
    emit_signal("coin_changed", _count)


func get_count() -> int:
    return _count


func save() -> void:
    var file := FileAccess.open(SAVE_PATH, FileAccess.WRITE)
    if not file:
        push_error("Failed to open save file for writing: %s" % SAVE_PATH)
        return
    file.store_string(JSON.stringify({"count": _count}))


func load_save() -> void:
    if not FileAccess.file_exists(SAVE_PATH):
        return
    var file := FileAccess.open(SAVE_PATH, FileAccess.READ)
    if not file:
        push_error("Failed to open save file for reading: %s" % SAVE_PATH)
        return
    var content := file.get_as_text()
    if content.is_empty():
        return
    var json := JSON.new()
    var error := json.parse(content)
    if error != OK:
        push_error("Failed to parse save file: %s" % json.get_error_message())
        return
    var data := json.data as Dictionary
    if data and "count" in data:
        _count = int(data["count"])
    emit_signal("coin_changed", _count)

