extends Node

signal coin_changed(new_count: int)

var _count: int = 0
const SAVE_PATH := "user://save.json"

func _ready() -> void:
    # Called on startup to restore the persisted coin count.
    load_save()


func add_coin() -> void:
    _count += 1
    save()
    emit_signal("coin_changed", _count)


func get_count() -> int:
    return _count


func save() -> void:
    var file := FileAccess.open(SAVE_PATH, FileAccess.WRITE)
    if not file:
        push_error("Failed to open save file for writing: %s" % SAVE_PATH)
        return
    file.store_string(JSON.stringify({"count": _count}))


func load_save() -> void:
    # NOTE: The public persistence API for restoring state.
    # Named `load_save()` because `load()` is a built-in global function in
    # GDScript that cannot be shadowed as a parameterless instance method.
    # This method reads `user://save.json`, restores the count and emits
    # `coin_changed` with the restored value.
    if not FileAccess.file_exists(SAVE_PATH):
        return
    var file := FileAccess.open(SAVE_PATH, FileAccess.READ)
    if not file:
        push_error("Failed to open save file for reading: %s" % SAVE_PATH)
        return
    var content := file.get_as_text()
    if content.is_empty():
        return
    var json := JSON.new()
    var error := json.parse(content)
    if error != OK:
        push_error("Failed to parse save file: %s" % json.get_error_message())
        return
    var data := json.data as Dictionary
    if data and "count" in data:
        _count = int(data["count"])
    emit_signal("coin_changed", _count)


func _notification(what: int) -> void:
    if what == NOTIFICATION_WM_CLOSE_REQUEST or what == NOTIFICATION_WM_GO_BACK_REQUEST:
        save()

extends Node2D

func _ready() -> void:
    var timer := Timer.new()
    add_child(timer)
    timer.wait_time = 0.5
    timer.one_shot = true
    timer.timeout.connect(_on_timeout)
    timer.start()

func _on_timeout() -> void:
    var player := get_node_or_null("Player")
    var coin := get_node_or_null("Coin")
    if player and coin:
        coin._on_body_entered(player)
        await get_tree().process_frame
    if not is_instance_valid(coin):
        print("COIN COLLECTED")
    var saved = FileAccess.get_file_as_string("user://save.json")
    print("saved: ", saved)
    get_tree().quit(0)

extends Node

func _ready() -> void:
    # Use Godot's built-in main path since global load() is shadowed by us.
    # To run test with autoloads initialized, we load the scene as root.
    var scene = preload("res://scenes/Main.tscn").instantiate()
    add_child(scene)
    await get_tree().process_frame

    # Initial state from autoload
    print("Initial count: ", Inventory.get_count())

    var player = scene.get_node("Player")
    var coin = scene.get_node("Coin")
    if is_instance_valid(coin):
        coin._on_body_entered(player)
    await get_tree().process_frame

    var saved = FileAccess.get_file_as_string("user://save.json")
    print("Post-collection JSON: ", saved)
    print("Autoload count: ", Inventory.get_count())

    # Verify HUD updated via signal
    var label = scene.get_node("HUD/Label")
    print("HUD text: ", label.text)

    await get_tree().process_frame
    get_tree().quit(0)
